Complete a receita do contexto do carrinho:

```jsx
const CarrinhoContext = ___(null);

export function useCarrinho() {
  const valor = ___(CarrinhoContext);
  if (!valor) throw new Error('useCarrinho precisa estar dentro do CarrinhoProvider');
  return valor;
}
```

